import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"安装与管理插件","description":"","frontmatter":{"title":"安装与管理插件","docId":"user.plugins.index","translationKey":"user.plugins.index","locale":"zh","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2892162f1f2ec94f8e5072f6689382b3c32c8546f2ad667a4651c721f597e84a","translationRevision":"44e8d6aae86ca2c477032e7ab3b41b069b05cb5519a335abc0e5ff54b39d568c","order":10},"headers":[],"relativePath":"zh/user/plugins/index.md","filePath":"zh/user/plugins/index.md","lastUpdated":1795727787000}`),s={name:`zh/user/plugins/index.md`};function c(a,o,s,c,l,u){let d=e(`TourFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="install-and-manage-plugins" tabindex="-1">安装与管理插件 <a class="header-anchor" href="#install-and-manage-plugins" aria-label="Permalink to “安装与管理插件”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前置条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “目标与前置条件”">​</a></h2><p>添加集成，审查其访问请求，并确认操作可用。桌面包需要兼容插件要求的操作系统、架构和宿主版本。远程目录及下载操作需要网络；部分基于账户的服务还需要<a href="./../cloud/account.html">登录 Cloud</a>。</p><h2 id="review-before-enabling" tabindex="-1">启用前审查 <a class="header-anchor" href="#review-before-enabling" aria-label="Permalink to “启用前审查”">​</a></h2><ol><li>打开 <strong>插件</strong>，查看已安装、探索或更新。探索仅请求插件条目。自动化模板与配置位于 <a href="./../automations/templates.html">自动化</a>。</li><li>选择插件，检查描述、版本、兼容性及运行时。核对发布者、请求的能力或权限，不要只凭熟悉的显示名称判断。</li><li>通过安装流程查看包预览。确认安装前，审查确切版本、签名信息、请求的访问权限，以及相对已安装版本的变化。</li><li>等待包作业结果。下载、安装和启用是不同阶段；仅有目录卡片不代表运行时已就绪。</li><li>打开插件的设置或连接面板。仅在指定字段中提供服务地址和凭据。如提供声明的连接检查，请使用它。</li><li>启用插件，再检查操作类型或页面是否出现。关联功能强大的外部操作前，先创建范围有限的<a href="./../automations/first-rule.html">日志规则</a>。</li></ol><p>插件可能运行原生代码或独立进程。进程边界可隔离崩溃，但不是操作系统沙箱。请安装来自可信发布者的软件。有效签名标识经过验证的包来源，但不代表每种效果都适合你的工作流程。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “预期结果与状态”">​</a></h2><p>包审查、安装作业、插件偏好设置及版本管理均可使用。实际操作取决于安装的清单、宿主能力及外部服务。事件处理器有自己的面板，可为事件添加可选分析字段；原始字段仍与之区分。</p><h2 id="recovery" tabindex="-1">恢复方法 <a class="header-anchor" href="#recovery" aria-label="Permalink to “恢复方法”">​</a></h2><p>安装失败时，阅读作业错误，检查兼容性、签名、运行时或下载问题。不要为了消除错误而降低验证要求。更新导致问题时，检查保留版本，并在可用时回滚。禁用或卸载插件前，审查依赖它的自动化。移除插件数据与配置前，请做好<a href="./../preferences/backups.html">备份</a>。</p>`,10),t(d,{id:`plugin`,locale:`zh`,title:`演示：插件`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">命令行操作 <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “命令行操作”">​</a></h2><p>本指南中的每个操作也可通过 CLI 使用——离线、可编写脚本、适合代理。用法行是解析器语法,在所有语言中保持英文。</p><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools plugin list</code></td><td>列出已安装的插件</td></tr><tr><td><code>tiktools plugin get &lt;id&gt;</code></td><td>读取一个插件</td></tr><tr><td><code>tiktools plugin install &lt;file.plugin&gt; [--replace] &amp;#124; plugin install &lt;id[@version]&amp;#124;url&gt; [--yes] [--no-wait] [--allow-unsigned]</code></td><td>从文件、id@version 或 url 安装</td></tr><tr><td><code>tiktools plugin uninstall &lt;id&gt; [--purge]</code></td><td>卸载插件 <strong>破坏性</strong></td></tr><tr><td><code>tiktools plugin search &lt;query&gt; [--category c] [--page N]</code></td><td>在注册表中搜索软件包</td></tr><tr><td><code>tiktools plugin inspect &lt;spec&gt;</code></td><td>安装前检查软件包规格</td></tr><tr><td><code>tiktools plugin outdated</code></td><td>列出有可用更新的已安装插件</td></tr><tr><td><code>tiktools plugin update &lt;id&gt; [--version v] [--yes] [--no-wait]</code></td><td>更新一个插件</td></tr><tr><td><code>tiktools plugin update --all [--yes] [--no-wait]</code></td><td>更新所有过时的插件</td></tr><tr><td><code>tiktools plugin rollback &lt;id&gt; [version] [--no-wait]</code></td><td>回滚到以前的版本 <strong>破坏性</strong></td></tr><tr><td><code>tiktools plugin versions &lt;id&gt;</code></td><td>列出插件的可用版本</td></tr><tr><td><code>tiktools plugin pin &lt;id&gt;</code></td><td>将插件固定到当前版本</td></tr><tr><td><code>tiktools plugin unpin &lt;id&gt;</code></td><td>移除版本固定</td></tr><tr><td><code>tiktools plugin policy &lt;id&gt; [--channel stable&amp;#124;beta] [--auto off&amp;#124;notify&amp;#124;patch&amp;#124;minor]</code></td><td>设置通道和自动更新策略</td></tr><tr><td><code>tiktools plugin jobs</code></td><td>列出软件包任务</td></tr><tr><td><code>tiktools plugin job &lt;job-id&gt;</code></td><td>检查一个软件包任务</td></tr><tr><td><code>tiktools plugin cancel &lt;job-id&gt;</code></td><td>取消正在运行的软件包任务 <strong>破坏性</strong></td></tr><tr><td><code>tiktools plugin enable &lt;id&gt;</code></td><td>启用插件</td></tr><tr><td><code>tiktools plugin disable &lt;id&gt;</code></td><td>禁用插件</td></tr><tr><td><code>tiktools plugin start &lt;id&gt;</code></td><td>启动插件</td></tr><tr><td><code>tiktools plugin stop &lt;id&gt;</code></td><td>停止插件 <strong>破坏性</strong></td></tr><tr><td><code>tiktools plugin settings get &lt;id&gt;</code></td><td>读取插件设置</td></tr><tr><td><code>tiktools plugin settings set &lt;id&gt; k=v...</code></td><td>写入插件设置</td></tr><tr><td><code>tiktools plugin settings reset &lt;id&gt;</code></td><td>重置插件设置 <strong>破坏性</strong></td></tr><tr><td><code>tiktools plugin health &lt;id&gt;</code></td><td>插件健康检查</td></tr><tr><td><code>tiktools plugin options &lt;action-type/field&gt;</code></td><td>动作类型或字段的选项</td></tr><tr><td><code>tiktools plugin action &lt;type&gt; [--config json] [--live]</code></td><td>运行插件动作</td></tr><tr><td><code>tiktools plugin commands</code></td><td>列出已安装插件贡献的命令</td></tr><tr><td><code>tiktools plugin help [id]</code></td><td>描述一个贡献的命令</td></tr><tr><td><code>tiktools plugin &lt;id&gt; &lt;command&gt; [--params json] [--live]</code></td><td>调用插件贡献的命令</td></tr></tbody></table><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools registry list</code></td><td>列出已配置的注册表</td></tr><tr><td><code>tiktools registry refresh</code></td><td>刷新注册表元数据</td></tr><tr><td><code>tiktools registry package &lt;id&gt;</code></td><td>显示一个注册表软件包</td></tr><tr><td><code>tiktools registry cloud-catalog [--query q] [--after cursor] [--generation value] [--target name]</code></td><td>搜索云目录</td></tr><tr><td><code>tiktools registry cloud-summaries [--query q] [--cursor value] [--generation value] [--target name]</code></td><td>云目录摘要页</td></tr><tr><td><code>tiktools registry cloud-versions &lt;id&gt; [--target name] [--generation value] [--cursor value]</code></td><td>云目录软件包的版本</td></tr><tr><td><code>tiktools registry cloud-pagination</code></td><td>云目录的分页能力</td></tr><tr><td><code>tiktools registry defaults</code></td><td>默认注册表配置</td></tr></tbody></table><table tabindex="0"><thead><tr><th>命令</th><th>摘要</th></tr></thead><tbody><tr><td><code>tiktools processor list</code></td><td>列出处理器</td></tr><tr><td><code>tiktools processor status</code></td><td>处理器管道状态</td></tr><tr><td><code>tiktools processor test &lt;plugin-id&gt; &lt;processor-id&gt; [event-json]</code></td><td>对示例事件运行一个处理器</td></tr></tbody></table><p>查看<a href="./../../developer/cli.html">完整命令参考</a>了解约定、JSON 输出和破坏性操作标记。</p>`,6)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};